#include <vector>
#include <algorithm>
int longest_zero_sum_subarray(std::vector<int> nums) {
    // correct but slow: it tries every start and every end
    int best = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        long long total = 0;
        for (size_t j = i; j < nums.size(); ++j) {
            total += nums[j];
            if (total == 0) best = std::max(best, (int)(j - i + 1));
        }
    }
    return best;
}

